import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.text.Normalizer;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;

public class AuditLogAgent {

    private static final String LOG_DIR = "/var/log/audit/";
    private static final Set<String> PRIVILEGED_SOURCES = Set.of(
        "system-monitor", "kernel-watchdog", "root-scheduler"
    );
    private static final Pattern SAFE_SOURCE_PATTERN = Pattern.compile("^[a-z0-9\\-]+$");
    private final ConcurrentHashMap<String, Integer> rateLimiter = new ConcurrentHashMap<>();
    private final Path logFile;
    private final Set<String> authenticatedPrivilegedTokens;

    public AuditLogAgent(String logFileName, Set<String> preSharedTokens) throws IOException {
        this.logFile = Paths.get(LOG_DIR, logFileName).normalize();
        if (!this.logFile.startsWith(LOG_DIR)) {
            throw new SecurityException("Path traversal detected");
        }
        Files.createDirectories(this.logFile.getParent());
        this.authenticatedPrivilegedTokens = Set.copyOf(preSharedTokens);
    }

    /**
     * Validates that the source identifier contains only safe ASCII characters.
     * This prevents injection of control characters or special sequences.
     * Uses codePoint iteration to correctly handle supplementary characters.
     */
    private boolean isValidSourceIdentifier(String source) {
        if (source == null || source.isEmpty() || source.length() > 64) {
            return false;
        }
        // Use codePoint iteration to correctly handle all Unicode
        for (int i = 0; i < source.length(); ) {
            int cp = source.codePointAt(i);
            if (!((cp >= 'a' && cp <= 'z') || (cp >= '0' && cp <= '9') || cp == '-')) {
                return false;
            }
            i += Character.charCount(cp);
        }
        return true;
    }

    /**
     * Normalizes the source identifier to canonical form.
     * Uses NFKC normalization to collapse compatibility equivalences.
     * IMPORTANT: Returns the same form used for both validation and privilege checks.
     */
    private String canonicalizeSource(String source) {
        String normalized = Normalizer.normalize(source, Normalizer.Form.NFKC);
        return normalized.toLowerCase(Locale.ROOT);
    }

    /**
     * Constant-time check of whether the provided token is among the
     * authenticated pre-shared tokens. Prevents timing side-channels (CWE-208)
     * that would otherwise leak information via String.equals short-circuiting.
     */
    private boolean isAuthenticatedToken(String authToken) {
        if (authToken == null || authToken.isEmpty()) {
            return false;
        }
        byte[] candidate = authToken.getBytes(StandardCharsets.UTF_8);
        boolean matched = false;
        for (String token : authenticatedPrivilegedTokens) {
            byte[] expected = token.getBytes(StandardCharsets.UTF_8);
            if (MessageDigest.isEqual(candidate, expected)) {
                matched = true;
            }
        }
        return matched;
    }

    /**
     * Determines if the log entry should be treated as privileged.
     * Requires BOTH source name match AND a valid pre-shared authentication token.
     * This prevents unauthorized privilege escalation via source name spoofing.
     */
    private boolean isPrivilegedSource(String source, String authToken) {
        if (authToken == null || authToken.isEmpty()) {
            return false;
        }
        // Canonicalize FIRST, then validate the canonical form
        String canonical = canonicalizeSource(source);
        if (!PRIVILEGED_SOURCES.contains(canonical)) {
            return false;
        }
        // Require valid authentication token for privilege
        return isAuthenticatedToken(authToken);
    }

    /**
     * Rate limits non-privileged sources to prevent log flooding.
     * Returns true if the message should be allowed through.
     */
    private boolean checkRateLimit(String source) {
        String canonical = canonicalizeSource(source);
        int count = rateLimiter.merge(canonical, 1, Integer::sum);
        return count <= 100;
    }

    /**
     * Core audit logging method. Accepts a source identifier, message, and auth token.
     * Validates the source, checks authenticated privileges, and writes the audit entry.
     */
    public synchronized void logAuditEvent(String source, String message, String severity, String authToken) throws IOException {
        // Step 1: Canonicalize first, then validate the canonical form
        String canonical = canonicalizeSource(source);

        if (!isValidSourceIdentifier(canonical)) {
            writeEntry("REJECTED", "invalid-source", "Source validation failed: " + sanitizeForLog(source));
            return;
        }

        // Step 2: Check if this is an authenticated privileged source
        boolean privileged = isPrivilegedSource(canonical, authToken);

        // Step 3: Apply rate limiting for non-privileged sources (using canonical form)
        if (!privileged && !checkRateLimit(canonical)) {
            return;
        }

        // Step 4: Sanitize message content
        String safeMessage = sanitizeForLog(message);
        String safeSeverity = severity != null && severity.matches("^(INFO|WARN|ERROR|CRITICAL)$") 
            ? severity : "INFO";

        // Step 5: Write the audit entry using CANONICAL source name
        String prefix = privileged ? "[PRIVILEGED] " : "";
        writeEntry(safeSeverity, canonical, prefix + safeMessage);

        // Step 6: Privileged sources also trigger immediate flush and alert
        if (privileged) {
            triggerPrivilegedAlert(canonical, safeMessage);
        }
    }

    private void writeEntry(String severity, String source, String message) throws IOException {
        long timestamp = System.currentTimeMillis();
        String entry = String.format("%d|%s|%s|%s%n", timestamp, severity, source, message);
        Files.writeString(logFile, entry, StandardCharsets.UTF_8, 
            StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    private void triggerPrivilegedAlert(String source, String message) {
        System.err.println("PRIVILEGED ALERT from " + source + ": " + message);
    }

    private String sanitizeForLog(String input) {
        if (input == null) return "<null>";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Math.min(input.length(), 1024); i++) {
            char c = input.charAt(i);
            if (c >= 0x20 && c < 0x7F) {
                sb.append(c);
            } else {
                sb.append(String.format("\\u%04x", (int) c));
            }
        }
        return sb.toString();
    }

    public void resetRateLimits() {
        rateLimiter.clear();
    }

    public static void main(String[] args) throws Exception {
        Set<String> tokens = Set.of("secret-token-12345");
        AuditLogAgent agent = new AuditLogAgent("audit.log", tokens);

        // Normal usage - no privilege without token
        agent.logAuditEvent("web-server", "Request processed", "INFO", null);
        // Privileged usage requires valid token
        agent.logAuditEvent("system-monitor", "CPU threshold exceeded", "CRITICAL", "secret-token-12345");
        // Attempted privilege escalation fails without valid token
        agent.logAuditEvent("root-scheduler", "Attacker message", "CRITICAL", "fake-token");
    }
}
